SELECT COALESCE(SUM(ve.DEBIT_AMOUNT), 0) FROM T_VOUCHER_ENTRY ve INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod} AND v.IS_DELETED = 0 AND (#{param.includeUnposted} = 1 OR v.VOUCHER_STATUS = 2) WHERE ve.IS_DELETED = 0
AND ve.SUBJECT_ID IN
#{subjectId}

SELECT COALESCE(SUM(ve.CREDIT_AMOUNT), 0) FROM T_VOUCHER_ENTRY ve INNER JOIN T_ACCOUNTING_VOUCHER v ON ve.VOUCHER_ID = v.VOUCHER_ID AND v.ACCOUNTING_PERIOD = #{param.accountingPeriod} AND v.IS_DELETED = 0 AND (#{param.includeUnposted} = 1 OR v.VOUCHER_STATUS = 2) WHERE ve.IS_DELETED = 0
AND ve.SUBJECT_ID IN
#{subjectId}

SELECT COUNT(DISTINCT ve.ACCOUNTING_PERIOD) as periodCount
FROM T_VOUCHER_ENTRY ve
WHERE ve.BOOK_ID = #{bookId}
AND ve.ACCOUNTING_PERIOD BETWEEN #{startPeriod} AND #{endPeriod}
AND ve.IS_DELETED = 0

SELECT TASK_ID as taskId, ACCOUNTING_PERIOD as accountingPeriod, BOOK_ID as bookId, CREATE_TIME as trialTime, IS_BALANCED as isBalanced, TOTAL_DEBIT as totalDebit, TOTAL_CREDIT as totalCredit, DIFFERENCE as difference FROM TBL_TRIAL_BALANCE_HISTORY WHERE BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId}
AND ACCOUNTING_PERIOD = #{period}
ORDER BY CREATE_TIME DESC
AND ROWNUM <= #{limit}

SELECT COUNT(1)
FROM T_VOUCHER_ENTRY
WHERE BOOK_ID = #{bookId}
AND ACCOUNTING_PERIOD = #{accountingPeriod}
AND IS_DELETED = 0
